// Calcula la fecha de ayer
const now = new Date();
const madridDate = new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Madrid' }).format(now);
const yesterday = new Date(madridDate);
yesterday.setDate(yesterday.getDate() - 1);
const date = yesterday.toISOString().split('T')[0];

const baseUrl = 'http://minio:9000/madrid-openmeteo-environment';

return [{
  json: {
    date,
    weatherUrl: `${baseUrl}/clean/historical_weather_hourly/date=${date}/weather_hourly.csv`,
    airUrl: `${baseUrl}/clean/air_quality_hourly/date=${date}/air_quality_hourly.csv`
  }
}];

// Parsea los dos CSVs descargados y genera las tablas curated
const date = $('Code in JavaScript').item.json.date;
const items = $input.all();

function parseCSV(text) {
  const lines = text.trim().split('\n');
  const headers = lines[0].split(',');
  return lines.slice(1).map(line => {
    const vals = line.split(',');
    return Object.fromEntries(headers.map((h, i) => [h, vals[i] ?? '']));
  });
}

const weatherText = items[0].json.body || items[0].json.data || '';
const airText = items[1].json.body || items[1].json.data || '';

const weatherRows = parseCSV(weatherText);
const airRows = parseCSV(airText);

// Tabla wide: une weather y air por hora (24 filas)
const wideRows = weatherRows.map((wr, i) => {
  const ar = airRows[i] || {};
  return {
    date: wr.date,
    time: wr.time,
    latitude: wr.latitude,
    longitude: wr.longitude,
    temperature_2m: wr.temperature_2m,
    precipitation: wr.precipitation,
    ozone: ar.ozone ?? '',
    carbon_dioxide: ar.carbon_dioxide ?? ''
  };
});

// Resumen diario: min/avg/max por variable (4 filas)
const variables = [
  { name: 'temperature_2m', source: 'open_meteo', dataset: 'historical_weather', unit: '°C' },
  { name: 'precipitation',  source: 'open_meteo', dataset: 'historical_weather', unit: 'mm' },
  { name: 'ozone',          source: 'open_meteo', dataset: 'air_quality',        unit: 'μg/m³' },
  { name: 'carbon_dioxide', source: 'open_meteo', dataset: 'air_quality',        unit: 'ppm' }
];

const summaryRows = variables.map(v => {
  const vals = wideRows
    .map(r => parseFloat(r[v.name]))
    .filter(n => !isNaN(n));
  const avg = vals.reduce((a, b) => a + b, 0) / vals.length;
  return {
    date,
    source: v.source,
    dataset: v.dataset,
    variable: v.name,
    unit: v.unit,
    observations: vals.length,
    min_value: Math.min(...vals).toFixed(4),
    avg_value: avg.toFixed(4),
    max_value: Math.max(...vals).toFixed(4)
  };
});

return [{ json: { date, wideRows, summaryRows } }];

// Genera el CSV de la tabla wide (hourly_environment_wide)
const { date, wideRows } = $input.item.json;
const fields = ['date','time','latitude','longitude','temperature_2m','precipitation','ozone','carbon_dioxide'];
const csv = [fields.join(','), ...wideRows.map(r => fields.map(f => r[f] ?? '').join(','))].join('\n');
return [{ json: { date, csv, fileName: 'hourly_environment_wide.csv', path: `curated/hourly_environment_wide/date=${date}/hourly_environment_wide.csv` } }];

